```javascript
function customSort(obj) {
  // Helper function for comparing keys
  const compareKeys = (a, b) => {
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
  };

  // Sort keys array and preserve the original order of equal keys
  const keys = Object.keys(obj).sort(compareKeys);

  // Generate sorted object
  return keys.reduce((acc, key) => {
    acc[key] = obj[key];
    return acc;
  }, {});
}

