function determineProtocol(inputData) {
  let ipVersion;
  if (inputData.sourceIP && inputData.destinationIP) {
    const sourceIPParts = inputData.sourceIP.split(":").length > 7 ? inputData.sourceIP.split(":") : inputData.sourceIP.match(/(\d+):/g).map(Number);
    const destIPParts = inputData.destinationIP.split(":").length > 7 ? inputData.destinationIP.split(":") : inputData.destinationIP.match(/(\d+):/g).map(Number);
    ipVersion = (sourceIPParts[0] === 0 && sourceIPParts[1] === 2001) || (destIPParts[0] === 0 && destIPParts[1] === 2001) ? 6 : 4; // Check for IPv6
  }
  let protocol;
  if (ipVersion === 6 && inputData.port === 80) {
    protocol = "HTTP over IPv6 (HTTPS uses the same port number but adds 's')";
  } else if (inputData.port === 80) {
    protocol = "HTTP";
  } else if (typeof inputData.payload !== "string" || !inputData.payload || inputData.payload.length <= 0) {
    protocol = "UDP (default protocol when no specific application layer protocol is indicated)";
  } else {
    protocol = "Application-specific protocol based on payload data";
  }
  console.log(`The most relevant protocol for this input data is ${protocol}`);
  return protocol;
}
determineProtocol(inputData);
