```javascript
import * as express from 'express';
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { JwtAuthGuard } from './auth/jwt-auth.guard';
import { RolesGuard } from './auth/roles.guard';
import * as fs from 'fs';
import passport from 'passport';
import { Strategy as JwtStrategy, ExtractJwt } from 'passport-jwt';
import { UserService } from './user/user.service';
import { Role } from './role/role.entity';

const app = express();
const port = process.env.PORT || 3000;

const jwtOptions = {
  secretOrKey: 'your_secret_key',
  jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
};

app.use(passport.initialize());
app.use(express.json());

passport.use(new JwtStrategy(jwtOptions, async (jwtPayload, done) => {
  const userService = new UserService();
  const user = await userService.validateUser(jwtPayload);
  if (!user) return done(null, false);
  return done(null, user);
}));

app.use((req, res, next) => {
  if ('accessToken' in req) {
    req.user = req.user;
  }
  next();
});

app.get('/api/permissions', async (req, res) => {
  const userRoles = await new UserService().findUserRoles(req.user.id);
  const allRoles = await new Role().find({ relations: ['permission'] });
  const permittedPermissions = allRoles.flatMap(role => role.permission).filter(p => userRoles.includes(role.name));
  res.send(permittedPermissions.map(p => p.name));
});

