```javascript
function geocodePlaces() {
  // Replace 'SheetName' with the name of your Google Spreadsheet sheet.
  const sheetName = "SheetName";
  const apiKey = "YOUR_API_KEY"; // Replace YOUR_API_KEY with your Google Maps API key

  // Get the active spreadsheet and sheet by name.
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);

  // Define the column number where place names are located.
  const placeColumnIndex = 1;

  // Define the columns numbers where latitude and longitude will be stored.
  const latColumnIndex = 2;
  const lngColumnIndex = 3;

  // Fetch data from the specified range.
  const dataRange = sheet.getDataRange();
  const values = dataRange.getValues();

  // Loop through each row and call the geocode function for each place name.
  for (let i = 0; i < values.length; i++) {
    const placeName = values[i][placeColumnIndex - 1];
    if (placeName) { // Skip empty cells
      const geocodedAddress = geocode(placeName, apiKey);
      if (geocodedAddress) { // Skip if geocoding fails
        values[i][latColumnIndex - 1] = geocodedAddress.results[0].geometry.location.lat;
        values[i][lngColumnIndex - 1] = geocodedAddress.results[0].geometry.location.lng;
      }
    }
  }

  // Update the sheet with new data.
  sheet.getRange(dataRange.getA1Notation()).setValues(values);
}

