       [HttpGet]
       [Route("usernamefromtoken")]
       public async Task<ActionResult<string>> GetUserNameFromToken([FromQuery] string jwtToken)
       {
           string username = await Task.Run(() => GetUsernameFromJwtToken(jwtToken));
           return Ok(username);
       }

