```c
#include <stdio.h>
#include <stdlib.h> // for malloc() and realloc()
#include <string.h> // for strlen() and strcat()

int main(int argc, char *argv[]) {
    size_t total_length = 0; // initial length of the final string
    size_t current_arg_length; // length of the current argument
    size_t i; // index variable

    // Calculate the total length of all the arguments concatenated together
    for (i = 0; i < argc; ++i) {
        current_arg_length = strlen(argv[i]) + 1; // add one for the space between arguments and null terminator
        total_length += current_arg_length;
    }

    // Allocate memory for the final string using malloc()
    char *final_string = malloc(total_length);
    if (!final_string) {
        fprintf(stderr, "Failed to allocate memory for final string\n");
        exit(EXIT_FAILURE);
    }

    // Concatenate all the arguments together
    for (i = 0; i < argc; ++i) {
        strcat(final_string, argv[i]);
        if (i < argc - 1) { // don't add a space after the last argument
            strcat(final_string, " ");
        }
    }

    // Print out the final string
    printf("Combined argument string: %s\n", final_string);

    // Don't forget to free the memory when you're done!
    free(final_string);

    return EXIT_SUCCESS;
}
```

