 Here's an example of a simple decorator for Nest.js middleware that checks the `NODE_ENV` environment variable and behaves accordingly:

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { NestMiddleware, MiddlewareFunction } from 'nest';

@NestMiddleware()
export class NodeEnvCheckDecorator implements NestMiddleware {
  use(req: Request, res: Response, next: Function, _: Function): void | Promise<void> {
    const nodeEnv: string | undefined = process.env.NODE_ENV;

    if (nodeEnv === 'true' || nodeEnv === 'production') { // adjust to your desired behavior
      next();
    } else {
      res.status(403).send(false);
    }
  }

  // Decorator for injecting the NodeEnvCheckDecorator as a middleware function
  static useNodeEnvChecker(middleware: MiddlewareFunction): MiddlewareFunction {
    return (req: Request, res: Response, next: Function) => {
      new NodeEnvCheckDecorator().use(req, res, next, () => middleware(req, res, next));
    };
  }
}

// Use the decorator in your controller or route handler
@Controller('api')
export class AppController {
  @Get()
  @UseGuards(AuthGuard()) // Assuming you have an AuthGuard middleware
  @UseMiddleware(NodeEnvCheckDecorator.useNodeEnvChecker(yourMiddlewareFunction)) // Add the NodeEnvCheckDecorator before your middleware
  getHello(@Req() req: Request, @Res() res: Response): any {
    return 'This is a protected API endpoint';
  }
}
```

This decorator, `NodeEnvCheckDecorator`, checks the `NODE_ENV` environment variable when the middleware is invoked. If the value is 'true' or 'production', it calls the next middleware function. Otherwise, it returns a `403 Forbidden` response with a boolean value of 'false'.

The decorator also includes a helper method, `useNodeEnvChecker`, which can be used to apply this behavior to other

