def num_to_words(num):
    # Helper functions for smaller parts of the number
    def thousands_place(num):
        if num >= 1000:
            return int_to_words(num // 1000) + " thousand"
        else:
            return ""

    def hundreds_place(num):
        if num >= 100:
            return int_to_words(num // 100) + " hundred"
        elif num > 0:
            return " and " + int_to_words(num)
        else:
            return ""

    def tens_and_ones_place(num):
        tens = num // 10
        ones = num % 10
        if tens > 0 or ones > 0:
            return (
                " "
                + int_to_words(tens * 10)
                + ("-" if tens > 0 and ones > 0 else "")
                + int_to_words(ones)
            )
        else:
            return ""

    def int_to_words(num):
        result = ""
        if num == 0:
            return "zero"
        elif num < 0:
