 To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Define a slice of specific negative words.
2. Split the given sentence into individual words.
3. Iterate through each word in the sentence and check if it is a negative word or if it is the word "not" followed by a negative word.
4. If both conditions are met, increment a counter and keep track of the index of the word.
5. After iterating through all the words, check if the counter is greater than zero.
6. If the counter is greater than zero, print a message indicating that the sentence contains a double negative.

Here's an example Go code snippet to accomplish this task:

```go
package main
import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"isn't", "am not", "doesn't", "does not", "hasn't", "haven't", "hadn't", "aren't", "is not", "are not", "wasn't", "weren't", "won't", "won't be", "can't", "can't be", "couldn't", "couldn't be"}
	sentence := "He isn't not worried about the coronavirus situation"
	words := strings.Split(sentence, " ")
	counter := 0
	for i, word := range words {
		if containsNegativeWord(word) || (i > 0 && words[i-1] == "not" && containsNegativeWord(words[i])) {
			counter++
		}
	}
	if counter > 0 {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func containsNegativeWord(word string) bool {
	for _, negWord := range negativeWords {
		if strings.EqualFold(negWord, word) {
			return true
		}
	}
	return false
}
```

