checkMNPStatusAPI(phoneNo, index) {
    console.log("mnpphoneno: " + phoneNo);

    const headers = new Headers();
    headers.append("Authorization", "Bearer " + user.getAccessToken());

    fetch(api.checkPortInStatus(user.getProductCode(), phoneNo), {
        headers: headers,
        method: 'GET'
    })
    .then(r => r.json())
    .then(rjson => {
        // Create a copy of the state to avoid mutating the original state directly
        let registrations = [...this.state.registrations];
        registrations[index].mnpStatus = rjson.status;

        // Update the state with the new data
        this.setState({ registrations });
    })
    .catch(error => console.error('Error:', error));
}
```

This will update the state with the new `mnpStatus` for the specific registration at the given index.

